def format_log_section(
    *, pass_id: str, ts: int, budget: str,
    picked: str, outcome: str, next_candidate: str,
) -> str:
    return (
        f"## pass {pass_id} (ts {ts})\n"
        f"budget: {budget}\n"
        f"picked: {picked}\n"
        f"outcome: {outcome}\n"
        f"next-candidate: {next_candidate}\n\n"
    )
